+    __ shift_left_add(hptr, mpos, hs, haystack_chr_shift, hptr /* tmp */);
@@ -4391,1 +4384,4 @@
-    // mismatch: check next candidate.
+
+    // mismatch: clear lowest bit and check next candidate.
+    __ addi(tmp, cand, -1);
+    __ andr(cand, tmp, cand);
@@ -4397,2 +4393,2 @@
